clc;
clear;
close all;

%% =========================
% Random Forest FROM SCRATCH - Feature Impact Study
% Liver Cirrhosis Stage Classification
%% =========================

%% Load dataset
data = readtable('liver_cirrhosis.csv');

disp('Dataset size:'); %[output:63325708]
disp(size(data)); %[output:9bf46c21]

%% =========================
% Basic Preprocessing
%% =========================

data = rmmissing(data, 'DataVariables', {'Stage'});

if iscell(data.Stage) || isstring(data.Stage) || iscategorical(data.Stage)
    data.Stage = double(categorical(data.Stage));
end

data = data(data.Stage >= 1 & data.Stage <= 3, :);

Y = data.Stage;

disp('Class counts:'); %[output:4144a9be]
tabulate(Y); %[output:41f3fbbb]

%% =========================
% Train / Validation / Test Split (70/15/15)
%% =========================

rng(1);

cv1 = cvpartition(Y, 'HoldOut', 0.30);
trainIdx = training(cv1);
tempIdx  = test(cv1);

YTemp = Y(tempIdx);
cv2 = cvpartition(YTemp, 'HoldOut', 0.50);

tempIndices = find(tempIdx);
valIdx  = false(size(Y));
testIdx = false(size(Y));
valIdx(tempIndices(training(cv2)))  = true;
testIdx(tempIndices(test(cv2)))     = true;

YTrain = Y(trainIdx);
YVal   = Y(valIdx);
YTest  = Y(testIdx);

fprintf('Training samples:   %d\n', sum(trainIdx)); %[output:7e65d180]
fprintf('Validation samples: %d\n', sum(valIdx)); %[output:40bb0536]
fprintf('Testing samples:    %d\n', sum(testIdx)); %[output:7a37fab0]

%% =========================
% Experiment Setup
%% =========================

baseRemoveVars  = {'Stage','ID','N_Days','Drug','Status'};
labFeatures     = {'Bilirubin','Albumin','Copper','Alk_Phos','SGOT', ...
                   'Tryglicerides','Platelets','Prothrombin','Cholesterol'};
symptomFeatures = {'Ascites','Hepatomegaly','Spiders','Edema'};

numTrees = 100;   % reduced from 200 — scratch is slow on 25k rows
maxDepth = 8;
minLeaf  = 3;

%% =========================
% Experiment 1: Baseline
%% =========================

[X_base, featNames_base] = makeFeatureMatrix(data, baseRemoveVars, false);
[XTrain_base, ~, XTest_base] = splitAndNormalize(X_base, trainIdx, valIdx, testIdx);

fprintf('\nTraining Experiment 1: Baseline RF...\n'); %[output:6c3a01f7]
[forest_base, imp_base] = trainForestScratch(XTrain_base, YTrain, numTrees, maxDepth, minLeaf);
pred_base = predictForestScratch(forest_base, XTest_base);
acc_base  = mean(pred_base == YTest) * 100;
fprintf('Baseline RF Accuracy: %.2f%%\n', acc_base); %[output:9c1638f3]

figure; %[output:96a67449]
confusionchart(YTest, pred_base); %[output:96a67449]
title(sprintf('Experiment 1: Baseline RF\nAccuracy: %.2f%%', acc_base)); %[output:96a67449]

plotImportanceScratch(imp_base, featNames_base, 'Feature Importance — Baseline RF'); %[output:581443a7]

%% =========================
% Experiment 2: Without Lab Features
%% =========================

[X_noLab, featNames_noLab] = makeFeatureMatrix(data, [baseRemoveVars, labFeatures], false);
[XTrain_noLab, ~, XTest_noLab] = splitAndNormalize(X_noLab, trainIdx, valIdx, testIdx);

fprintf('\nTraining Experiment 2: Without Lab Features...\n'); %[output:2abb15eb]
[forest_noLab, imp_noLab] = trainForestScratch(XTrain_noLab, YTrain, numTrees, maxDepth, minLeaf);
pred_noLab = predictForestScratch(forest_noLab, XTest_noLab);
acc_noLab  = mean(pred_noLab == YTest) * 100;
fprintf('Without Lab Features Accuracy: %.2f%%\n', acc_noLab); %[output:514f30af]

figure; %[output:77fdccee]
confusionchart(YTest, pred_noLab); %[output:77fdccee]
title(sprintf('Experiment 2: Without Lab Features\nAccuracy: %.2f%%', acc_noLab)); %[output:77fdccee]

plotImportanceScratch(imp_noLab, featNames_noLab, 'Feature Importance — Without Lab Features'); %[output:0e722e78]

%% =========================
% Experiment 3: Without Symptom Features
%% =========================

[X_noSym, featNames_noSym] = makeFeatureMatrix(data, [baseRemoveVars, symptomFeatures], false);
[XTrain_noSym, ~, XTest_noSym] = splitAndNormalize(X_noSym, trainIdx, valIdx, testIdx);

fprintf('\nTraining Experiment 3: Without Symptom Features...\n'); %[output:1ee5fceb]
[forest_noSym, imp_noSym] = trainForestScratch(XTrain_noSym, YTrain, numTrees, maxDepth, minLeaf);
pred_noSym = predictForestScratch(forest_noSym, XTest_noSym);
acc_noSym  = mean(pred_noSym == YTest) * 100;
fprintf('Without Symptom Features Accuracy: %.2f%%\n', acc_noSym); %[output:70a76284]

figure; %[output:25837ebb]
confusionchart(YTest, pred_noSym); %[output:25837ebb]
title(sprintf('Experiment 3: Without Symptom Features\nAccuracy: %.2f%%', acc_noSym)); %[output:25837ebb]

plotImportanceScratch(imp_noSym, featNames_noSym, 'Feature Importance — Without Symptom Features'); %[output:93fd6d7e]

%% =========================
% Experiment 4: With Engineered Features
%% =========================

[X_eng, featNames_eng] = makeFeatureMatrix(data, baseRemoveVars, true);
[XTrain_eng, ~, XTest_eng] = splitAndNormalize(X_eng, trainIdx, valIdx, testIdx);

fprintf('\nTraining Experiment 4: With Engineered Features...\n'); %[output:47ce48b7]
[forest_eng, imp_eng] = trainForestScratch(XTrain_eng, YTrain, numTrees, maxDepth, minLeaf);
pred_eng = predictForestScratch(forest_eng, XTest_eng);
acc_eng  = mean(pred_eng == YTest) * 100;
fprintf('With Engineered Features Accuracy: %.2f%%\n', acc_eng); %[output:878640c1]

figure; %[output:4f62a478]
confusionchart(YTest, pred_eng); %[output:4f62a478]
title(sprintf('Experiment 4: With Engineered Features\nAccuracy: %.2f%%', acc_eng)); %[output:4f62a478]

plotImportanceScratch(imp_eng, featNames_eng, 'Feature Importance — With Engineered Features'); %[output:9509a214]

%% =========================
% Final Results Table + Bar Chart
%% =========================

Experiment = {'Baseline RF'; 'Without Lab Features'; ...
              'Without Symptom Features'; 'With Engineered Features'};
Accuracy   = [acc_base; acc_noLab; acc_noSym; acc_eng];

resultsTable = table(Experiment, Accuracy);
disp('Final Feature Impact Results:'); %[output:392c22ad]
disp(resultsTable); %[output:85cb7742]

figure; %[output:68777092]
b = bar(Accuracy, 'FaceColor', 'flat'); %[output:68777092]
b.CData = [0.2 0.6 0.9; 0.9 0.4 0.2; 0.3 0.8 0.4; 0.8 0.3 0.8]; %[output:68777092]
set(gca, 'XTickLabel', Experiment, 'XTickLabelRotation', 20, 'FontSize', 10); %[output:68777092]
ylabel('Accuracy (%)'); %[output:68777092]
title('From-Scratch RF — Feature Impact Analysis'); %[output:68777092]
ylim([0 100]); %[output:68777092]
grid on; %[output:68777092]
for i = 1:4 %[output:group:9100aa20]
    text(i, Accuracy(i) + 1, sprintf('%.2f%%', Accuracy(i)), ... %[output:68777092]
        'HorizontalAlignment', 'center', 'FontSize', 10, 'FontWeight', 'bold'); %[output:68777092]
end %[output:group:9100aa20]

%% =========================
% Best Model Precision & Recall
%% =========================

[bestAcc, bestIdx] = max(Accuracy);
fprintf('\nBest Model: %s\n', Experiment{bestIdx}); %[output:4914b179]
fprintf('Best Accuracy: %.2f%%\n', bestAcc); %[output:8650d73b]

allPreds = {pred_base, pred_noLab, pred_noSym, pred_eng};
bestPred = allPreds{bestIdx};

cm        = confusionmat(YTest, bestPred);
precision = diag(cm) ./ sum(cm, 1)';
recall    = diag(cm) ./ sum(cm, 2);

fprintf('\nPrecision per class (Best Model):\n'); disp(precision); %[output:5f11da4e]
fprintf('Recall per class (Best Model):\n');    disp(recall); %[output:0563fdb7]

%% ============================================================
% FROM SCRATCH — Core Functions
%% ============================================================

%% --- Train Random Forest ---
function [forest, featureImportance] = trainForestScratch(XTrain, YTrain, numTrees, maxDepth, minLeaf)
    n           = size(XTrain, 1);
    numFeatures = size(XTrain, 2);
    mtry        = max(1, round(sqrt(numFeatures)));
    forest      = cell(numTrees, 1);

    % Track how many times each feature is used for splitting
    featureImportance = zeros(1, numFeatures);

    for t = 1:numTrees
        % Bootstrap sample
        bootIdx = randi(n, n, 1);
        Xb = XTrain(bootIdx, :);
        Yb = YTrain(bootIdx);

        % Build one tree, accumulate importance
        [forest{t}, treeImp] = buildTree(Xb, Yb, maxDepth, minLeaf, mtry, numFeatures);
        featureImportance     = featureImportance + treeImp;
    end

    % Normalize importance across all trees
    totalImp = sum(featureImportance);
    if totalImp > 0
        featureImportance = featureImportance / totalImp;
    end
end

%% --- Predict with Random Forest (majority vote) ---
function predictions = predictForestScratch(forest, XTest)
    numTrees = length(forest);
    nTest    = size(XTest, 1);
    allPreds = zeros(nTest, numTrees);

    for t = 1:numTrees
        allPreds(:, t) = predictTree(forest{t}, XTest);
    end

    predictions = zeros(nTest, 1);
    for i = 1:nTest
        predictions(i) = mode(allPreds(i, :));
    end
end

%% --- Build Decision Tree (recursive) ---
function [node, importance] = buildTree(X, Y, maxDepth, minLeaf, mtry, numFeatures)
    importance       = zeros(1, numFeatures);
    node.isLeaf      = false;
    node.prediction  = mode(Y);

    % Stop conditions
    if maxDepth == 0 || length(Y) <= minLeaf || length(unique(Y)) == 1
        node.isLeaf = true;
        return;
    end

    [splitFeat, splitVal, gain] = findBestSplit(X, Y, mtry);

    if gain == 0
        node.isLeaf = true;
        return;
    end

    leftIdx  = X(:, splitFeat) <= splitVal;
    rightIdx = ~leftIdx;

    if sum(leftIdx) < minLeaf || sum(rightIdx) < minLeaf
        node.isLeaf = true;
        return;
    end

    % Count this feature split in importance
    importance(splitFeat) = importance(splitFeat) + gain;

    node.splitFeature = splitFeat;
    node.splitValue   = splitVal;

    [node.left,  impLeft]  = buildTree(X(leftIdx,  :), Y(leftIdx),  maxDepth-1, minLeaf, mtry, numFeatures);
    [node.right, impRight] = buildTree(X(rightIdx, :), Y(rightIdx), maxDepth-1, minLeaf, mtry, numFeatures);

    % Accumulate child importances
    importance = importance + impLeft + impRight;
end

%% --- Find Best Split using Gini Impurity ---
function [bestFeat, bestVal, bestGain] = findBestSplit(X, Y, mtry)
    n            = size(X, 1);
    numFeatures  = size(X, 2);
    featIdx      = randperm(numFeatures, min(mtry, numFeatures));
    bestFeat     = 1;
    bestVal      = 0;
    bestGain     = 0;
    parentGini   = giniImpurity(Y);

    for f = featIdx
        vals = unique(X(:, f));
        if length(vals) < 2
            continue;
        end
        thresholds = (vals(1:end-1) + vals(2:end)) / 2;

        for v = 1:length(thresholds)
            thr    = thresholds(v);
            leftY  = Y(X(:, f) <= thr);
            rightY = Y(X(:, f) >  thr);

            if isempty(leftY) || isempty(rightY)
                continue;
            end

            gain = parentGini ...
                 - (length(leftY)/n)  * giniImpurity(leftY) ...
                 - (length(rightY)/n) * giniImpurity(rightY);

            if gain > bestGain
                bestGain = gain;
                bestFeat = f;
                bestVal  = thr;
            end
        end
    end
end

%% --- Gini Impurity ---
function g = giniImpurity(Y)
    n = length(Y);
    if n == 0
        g = 0;
        return;
    end
    classes = unique(Y);
    g = 1;
    for c = 1:length(classes)
        p = sum(Y == classes(c)) / n;
        g = g - p^2;
    end
end

%% --- Predict with a Single Tree ---
function preds = predictTree(node, X)
    nTest = size(X, 1);
    preds = zeros(nTest, 1);
    for i = 1:nTest
        preds(i) = traverseTree(node, X(i, :));
    end
end

%% --- Traverse Tree ---
function label = traverseTree(node, x)
    if node.isLeaf
        label = node.prediction;
        return;
    end
    if x(node.splitFeature) <= node.splitValue
        label = traverseTree(node.left,  x);
    else
        label = traverseTree(node.right, x);
    end
end

%% ============================================================
% Helper Functions
%% ============================================================

%% --- Plot Feature Importance ---
function plotImportanceScratch(importance, featureNames, titleStr)
    [sortedImp, sortIdx] = sort(importance, 'descend');
    sortedNames = featureNames(sortIdx);

    figure;
    bar(sortedImp, 'FaceColor', [0.2 0.6 0.85]);
    xticks(1:length(sortedImp));
    xticklabels(sortedNames);
    xtickangle(45);
    ylabel('Importance Score (Gini Gain)');
    title(titleStr);
    grid on;
    set(gca, 'FontSize', 9);
end

%% --- Make Feature Matrix ---
function [X, featureNames] = makeFeatureMatrix(data, varsToRemove, addEngineered)
    varsToRemove = intersect(varsToRemove, data.Properties.VariableNames);
    Xtable = removevars(data, varsToRemove);

    if addEngineered

        % 1. Bilirubin / Albumin ratio
        if all(ismember({'Bilirubin','Albumin'}, Xtable.Properties.VariableNames))
            Xtable.Bili_Albumin_Ratio = Xtable.Bilirubin ./ Xtable.Albumin;
            Xtable.Bili_Albumin_Ratio(~isfinite(Xtable.Bili_Albumin_Ratio)) = 0;
        end

        % 2. Liver Stress Score
        if all(ismember({'Bilirubin','SGOT','Alk_Phos'}, Xtable.Properties.VariableNames))
            Xtable.LiverStressScore = Xtable.Bilirubin + Xtable.SGOT + Xtable.Alk_Phos;
        end

        % 3. Coagulation Risk
        if all(ismember({'Prothrombin','Platelets'}, Xtable.Properties.VariableNames))
            Xtable.CoagulationRisk = Xtable.Prothrombin ./ Xtable.Platelets;
            Xtable.CoagulationRisk(~isfinite(Xtable.CoagulationRisk)) = 0;
        end

        % 4. Log Bilirubin
        if ismember('Bilirubin', Xtable.Properties.VariableNames)
            Xtable.Log_Bilirubin = log(Xtable.Bilirubin + 1);
        end

        % 5. Log Alk_Phos
        if ismember('Alk_Phos', Xtable.Properties.VariableNames)
            Xtable.Log_Alk_Phos = log(Xtable.Alk_Phos + 1);
        end

        % 6. Log SGOT
        if ismember('SGOT', Xtable.Properties.VariableNames)
            Xtable.Log_SGOT = log(Xtable.SGOT + 1);
        end

        % 7. MELD Score approximation
        if all(ismember({'Bilirubin','Prothrombin'}, Xtable.Properties.VariableNames))
            Xtable.MELD_Score = 3.78 .* log(Xtable.Bilirubin + 1) + ...
                                11.2 .* log(Xtable.Prothrombin + 1) + 6.43;
        end

        % 8. Child-Pugh Proxy
        if all(ismember({'Albumin','Bilirubin','Prothrombin'}, Xtable.Properties.VariableNames))
            Xtable.ChildPugh_Proxy = Xtable.Bilirubin + Xtable.Prothrombin - Xtable.Albumin;
        end

        % 9. Copper / Albumin ratio
        if all(ismember({'Copper','Albumin'}, Xtable.Properties.VariableNames))
            Xtable.Copper_Albumin_Ratio = Xtable.Copper ./ Xtable.Albumin;
            Xtable.Copper_Albumin_Ratio(~isfinite(Xtable.Copper_Albumin_Ratio)) = 0;
        end
    end

    categoricalVars = {'Sex','Ascites','Hepatomegaly','Spiders','Edema'};
    categoricalVars = intersect(categoricalVars, Xtable.Properties.VariableNames);

    for i = 1:length(categoricalVars)
        Xtable.(categoricalVars{i}) = categorical(Xtable.(categoricalVars{i}));
    end

    numericVars = setdiff(Xtable.Properties.VariableNames, categoricalVars);

    for i = 1:length(numericVars)
        Xtable.(numericVars{i}) = fillmissing(Xtable.(numericVars{i}), 'constant', 0);
    end

    for i = 1:length(categoricalVars)
        cats = categories(Xtable.(categoricalVars{i}));
        if ~ismember("Missing", string(cats))
            Xtable.(categoricalVars{i}) = addcats(Xtable.(categoricalVars{i}), "Missing");
        end
        Xtable.(categoricalVars{i}) = fillmissing(Xtable.(categoricalVars{i}), 'constant', "Missing");
    end

    Xnum = table2array(Xtable(:, numericVars));
    Xcat = [];
    catFeatureNames = {};

    for i = 1:length(categoricalVars)
        c = Xtable.(categoricalVars{i});
        d = dummyvar(c);
        Xcat = [Xcat, d];
        cats = categories(c);
        for j = 1:length(cats)
            catFeatureNames{end+1} = sprintf('%s_%s', categoricalVars{i}, string(cats{j}));
        end
    end

    X = [Xnum, Xcat];
    featureNames = [numericVars, catFeatureNames];
end

%% --- Split and Normalize ---
function [XTrain, XVal, XTest] = splitAndNormalize(X, trainIdx, valIdx, testIdx)
    XTrain = X(trainIdx, :);
    XVal   = X(valIdx,   :);
    XTest  = X(testIdx,  :);

    mu    = mean(XTrain, 1);
    sigma = std(XTrain, 0, 1);
    sigma(sigma == 0) = 1;

    XTrain = (XTrain - mu) ./ sigma;
    XVal   = (XVal   - mu) ./ sigma;
    XTest  = (XTest  - mu) ./ sigma;
end

